            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd152v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd152v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd152v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd152v)row);
        public void Dispose() => writer.Dispose();
    }
}